import sys


def main() -> None:
    first = sys.stdin.buffer.readline()
    if not first:
        return

    count = int(first)
    if count == 0:
        sys.stdout.write("\n")
        return

    prefix = sys.stdin.buffer.readline().rstrip(b"\r\n")
    for _ in range(count - 1):
        line = sys.stdin.buffer.readline().rstrip(b"\r\n")
        limit = min(len(prefix), len(line))
        index = 0
        while index < limit and prefix[index] == line[index]:
            index += 1
        prefix = prefix[:index]

    sys.stdout.buffer.write(prefix + b"\n")


if __name__ == "__main__":
    main()

