use std::io::{self, BufRead};

fn main() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let n: usize = lines
        .next()
        .and_then(Result::ok)
        .and_then(|line| line.trim().parse().ok())
        .unwrap_or(0);

    if n == 0 {
        println!();
        return;
    }

    let mut prefix = lines.next().and_then(Result::ok).unwrap_or_default();

    for _ in 1..n {
        let line = lines.next().and_then(Result::ok).unwrap_or_default();
        let common_len = prefix
            .bytes()
            .zip(line.bytes())
            .take_while(|(a, b)| a == b)
            .count();
        prefix.truncate(common_len);
    }

    println!("{prefix}");
}

