use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let n: usize = values.next().unwrap().parse().unwrap();
    let k: usize = values.next().unwrap().parse().unwrap();
    let numbers: Vec<i128> = values
        .take(n)
        .map(|value| value.parse().unwrap())
        .collect();

    let mut sum: i128 = numbers[..k].iter().sum();
    let mut output = sum.to_string();

    for end in k..n {
        sum += numbers[end] - numbers[end - k];
        output.push(',');
        output.push_str(&sum.to_string());
    }

    println!("{output}");
}

