import sys


def main() -> None:
    first_line = sys.stdin.buffer.readline()
    if not first_line:
        return

    count = int(first_line)
    if count == 0:
        return

    votes: dict[str, int] = {}
    for _ in range(count):
        name = sys.stdin.buffer.readline().decode("ascii").rstrip("\r\n")
        votes[name] = votes.get(name, 0) + 1

    winner, total = min(votes.items(), key=lambda item: (-item[1], item[0]))
    print(winner, total)


if __name__ == "__main__":
    main()

