import sys


def main() -> None:
    line = sys.stdin.readline().rstrip("\r\n")
    if not line:
        print()
        return

    groups: list[str] = []
    current = line[0]
    count = 1

    for letter in line[1:]:
        if letter == current:
            count += 1
        else:
            groups.append(f"{current}:{count}")
            current = letter
            count = 1

    groups.append(f"{current}:{count}")
    print(",".join(groups))


if __name__ == "__main__":
    main()

